        return 0;
    }

    for (int i = 0; i < T; ++i) {
        string line;
        if (!getline(cin, line)) break;

        string s = trim_string(line);
        cout << (valid_parens(s) ? "YES" : "NO") << '\n';
    }

    return 0;
}
